package org.jfree.chart.plot;

import java.awt.Paint;
import java.awt.Stroke;
import java.io.*;
import java.math.*;
import java.util.*;
import org.jfree.chart.event.MarkerChangeEvent;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ValueMarker.equals(Object)
 */
public class ValueMarker_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        ValueMarker marker = new ValueMarker(10.0);
        // Covers: if (obj == this) return true;
        assertTrue(marker.equals(marker));
    }

    @Test
    public void testEquals_SuperEqualsFalse() {
        // Since ValueMarker inherits from a class (likely Marker or Shape), 
        // we need to test the case where super.equals(obj) returns false.
        // In JFreeChart, ValueMarker is a subclass of Marker. 
        // If we compare it to a completely different object type that fails super.equals,
        // it covers the second if block.
        ValueMarker marker = new ValueMarker(10.0);
        Object differentObject = new Object();

        // Covers: if (!super.equals(obj)) return false;
        assertFalse(marker.equals(differentObject));
    }

    @Test
    public void testEquals_NotInstanceOfValueMarker() {
        ValueMarker marker = new ValueMarker(10.0);
        // We need an object that passes super.equals (if possible) but is not a ValueMarker.
        // However, since we don't have the implementation of the superclass, 
        // we assume a null or different type that fails 'instanceof'.
        // If super.equals(null) is false, it hits the second block. 
        // To specifically hit '!(obj instanceof ValueMarker)', the superclass must return true for a non-ValueMarker.
        // For the purpose of this test, providing a different class that might share a superclass:

        // Testing null specifically (usually super.equals returns false for null)
        assertFalse(marker.equals(null));
    }

    @Test
    public void testEquals_DifferentValue() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(20.0);

        // We assume super.equals returns true because they are both ValueMarkers 
        // (assuming Marker.equals is implemented to check type or is identity-based).
        // To ensure we reach the value check, we rely on the fact that they are both ValueMarkers.
        // If super.equals(marker2) is true:
        // Covers: if (this.value != that.value) return false;
        assertFalse(marker1.equals(marker2));
    }

    @Test
    public void testEquals_SameValue() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(10.0);

        // Covers: return true; (the final return statement)
        assertTrue(marker1.equals(marker2));
    }

    @Test
    public void testEquals_WithComplexConstructor() {
        // Testing that the complex constructor doesn't break equality logic
        ValueMarker marker1 = new ValueMarker(10.0, java.awt.Color.RED, null, java.awt.Color.BLACK, null, 1.0f);
        ValueMarker marker2 = new ValueMarker(10.0, java.awt.Color.RED, null, java.awt.Color.BLACK, null, 1.0f);

        assertTrue(marker1.equals(marker2));
    }
}
